{
  "items": [
    {
      "name": "Finset.sup'_singleton",
      "type": " {α : Type u_2} {β : Type u_3} [SemilatticeSup α] (f : β → α) {b : β} : {b}.sup' ⋯ f = f b",
      "module": "Mathlib.Data.Finset.Lattice.Fold"
    },
    {
      "name": "Finset.sup'_le",
      "type": " {α : Type u_2} {β : Type u_3} [SemilatticeSup α] {s : Finset β} (H : s.Nonempty) (f : β → α) {a : α} : (∀ b ∈ s, f b ≤ a) → s.sup' H f ≤ a",
      "module": "Mathlib.Data.Finset.Lattice.Fold"
    },
    {
      "name": "Finset.le_sup'",
      "type": " {α : Type u_2} {β : Type u_3} [SemilatticeSup α] {s : Finset β} (f : β → α) {b : β} (h : b ∈ s) : f b ≤ s.sup' ⋯ f",
      "module": "Mathlib.Data.Finset.Lattice.Fold"
    },
    {
      "name": "Finset.sup'_le_iff",
      "type": " {α : Type u_2} {β : Type u_3} [SemilatticeSup α] {s : Finset β} (H : s.Nonempty) (f : β → α) {a : α} : s.sup' H f ≤ a ↔ ∀ b ∈ s, f b ≤ a",
      "module": "Mathlib.Data.Finset.Lattice.Fold"
    },
    {
      "name": "Finset.sup'_inf_distrib_left",
      "type": " {α : Type u_2} {ι : Type u_5} [DistribLattice α] {s : Finset ι} (hs : s.Nonempty) (f : ι → α) (a : α) : a ⊓ s.sup' hs f = s.sup' hs fun i => a ⊓ f i",
      "module": "Mathlib.Data.Finset.Lattice.Fold"
    },
    {
      "name": "Finset.le_sup'_of_le",
      "type": " {α : Type u_2} {β : Type u_3} [SemilatticeSup α] {s : Finset β} (f : β → α) {a : α} {b : β} (hb : b ∈ s) (h : a ≤ f b) : a ≤ s.sup' ⋯ f",
      "module": "Mathlib.Data.Finset.Lattice.Fold"
    },
    {
      "name": "Finset.le_sup'_iff",
      "type": " {α : Type u_2} {ι : Type u_5} [LinearOrder α] {s : Finset ι} (H : s.Nonempty) {f : ι → α} {a : α} : a ≤ s.sup' H f ↔ ∃ b ∈ s, a ≤ f b",
      "module": "Mathlib.Data.Finset.Lattice.Fold"
    },
    {
      "name": "Finset.sup'_product_left",
      "type": " {α : Type u_1} {β : Type u_2} {γ : Type u_3} [SemilatticeSup α] {s : Finset β} {t : Finset γ} (h : (s ×ˢ t).Nonempty) (f : β × γ → α) : (s ×ˢ t).sup' h f = s.sup' ⋯ fun i => t.sup' ⋯ fun i' => f (i, i')",
      "module": "Mathlib.Data.Finset.Lattice.Prod"
    }
  ]
}
